using UnityEngine;
public class VillagerGesture:MonoBehaviour {
 public Animator animator;public DemoInteractable interaction;public Transform player,trail,emblem,forestGoal,mentor;
 public float lowerSeconds=.45f,pauseSeconds=1.5f,raiseSeconds=.55f;
 public enum Pose{Clasp,Lowering,Waiting,Pointing}
 public Pose Current{get;private set;}public float LoweredAt{get;private set;}public float PointStartedAt{get;private set;}public Transform PointTarget{get;private set;}
 float since,lowerFromClasp=1,lowerFromPoint;bool subscribed;
 void OnEnable(){if(!animator)animator=GetComponent<Animator>();if(!interaction)interaction=GetComponentInParent<DemoInteractable>();if(interaction){interaction.Activated+=Interact;subscribed=true;}Current=Pose.Clasp;}
 void OnDisable(){if(subscribed&&interaction)interaction.Activated-=Interact;subscribed=false;}
 public void Interact(){if(Current==Pose.Lowering||Current==Pose.Waiting)return;lowerFromClasp=ClaspWeight();lowerFromPoint=PointWeight();Current=Pose.Lowering;since=Time.time;PointTarget=ChooseTarget();}
 Transform ChooseTarget(){var inv=player?player.GetComponent<DemoInvestigation>():null;var flow=player?player.GetComponent<DemoPrologueFlow>():null;if(inv&&!inv.HasTrail&&trail)return trail;if(inv&&!inv.HasEvidence&&emblem)return emblem;if(flow&&flow.Current==DemoPrologueFlow.Stage.MentorClue&&mentor)return mentor;return forestGoal?forestGoal:trail;}
 void Update(){if(player){var d=player.position-transform.position;d.y=0;if(d.sqrMagnitude<144&&d.sqrMagnitude>.01f){var facing=Quaternion.LookRotation(d);if(Current==Pose.Pointing&&PointTarget){var goal=PointTarget.position-transform.position;goal.y=0;if(goal.sqrMagnitude>.01f)facing=Quaternion.RotateTowards(facing,Quaternion.LookRotation(goal),65);}transform.rotation=Quaternion.Slerp(transform.rotation,facing,1-Mathf.Exp(-Time.deltaTime*5));}if(d.sqrMagnitude>64&&Current==Pose.Pointing)Current=Pose.Clasp;}
 if(Current==Pose.Lowering&&Time.time-since>=lowerSeconds){Current=Pose.Waiting;since=Time.time;LoweredAt=Time.time;}else if(Current==Pose.Waiting&&Time.time-since>=pauseSeconds){Current=Pose.Pointing;since=Time.time;PointStartedAt=Time.time;}
 if(animator&&animator.layerCount>2){float clasp=ClaspWeight();animator.SetLayerWeight(1,clasp);animator.SetLayerWeight(2,PointWeight());}}
 float ClaspWeight()=>Current==Pose.Clasp?1:Current==Pose.Lowering?lowerFromClasp*(1-Mathf.SmoothStep(0,1,Mathf.Clamp01((Time.time-since)/lowerSeconds))):0;
 float PointWeight()=>Current==Pose.Lowering?lowerFromPoint*(1-Mathf.SmoothStep(0,1,Mathf.Clamp01((Time.time-since)/lowerSeconds))):Current==Pose.Pointing?Mathf.SmoothStep(0,1,Mathf.Clamp01((Time.time-since)/raiseSeconds)):0;
 void OnAnimatorIK(int layer){if(layer!=0||!animator)return;float clasp=ClaspWeight(),point=PointWeight();var origin=transform.position;var rot=transform.rotation;float breath=Mathf.Sin(Time.time*1.6f)*.006f;Vector3 left=origin+rot*new Vector3(-.075f,1.31f+breath,.29f),right=origin+rot*new Vector3(.075f,1.31f+breath,.29f);Quaternion leftRot=rot*Quaternion.Euler(0,65,-70),rightRot=rot*Quaternion.Euler(0,-65,70);
 if(point>0&&PointTarget){var shoulder=animator.GetBoneTransform(HumanBodyBones.LeftUpperArm).position;var direction=PointTarget.position+Vector3.up*.8f-shoulder;direction.y=Mathf.Clamp(direction.y,-.15f,.2f);direction.Normalize();left=shoulder+direction*.59f;leftRot=Quaternion.LookRotation(direction,Vector3.up)*Quaternion.Euler(0,0,90);}
 SetHand(AvatarIKGoal.LeftHand,left,leftRot,Mathf.Max(clasp,point));SetHand(AvatarIKGoal.RightHand,right,rightRot,clasp);animator.SetIKHintPositionWeight(AvatarIKHint.LeftElbow,Mathf.Max(clasp,point)*.7f);animator.SetIKHintPosition(AvatarIKHint.LeftElbow,origin+rot*new Vector3(-.38f,1.02f,.1f));animator.SetIKHintPositionWeight(AvatarIKHint.RightElbow,clasp*.7f);animator.SetIKHintPosition(AvatarIKHint.RightElbow,origin+rot*new Vector3(.38f,1.02f,.1f));if(player){animator.SetLookAtWeight(.45f,.05f,.7f,.4f,.6f);animator.SetLookAtPosition(player.position+Vector3.up*1.55f);}}
 void LateUpdate(){if(Current!=Pose.Pointing||!PointTarget)return;var hand=animator.GetBoneTransform(HumanBodyBones.LeftHand);var first=animator.GetBoneTransform(HumanBodyBones.LeftIndexProximal);var last=animator.GetBoneTransform(HumanBodyBones.LeftIndexDistal);if(!hand||!first||!last)return;var d=PointTarget.position-hand.position;d.y=0;d.Normalize();var desired=Quaternion.FromToRotation(last.position-first.position,d)*hand.rotation;hand.rotation=Quaternion.Slerp(hand.rotation,desired,PointWeight());}
 void SetHand(AvatarIKGoal goal,Vector3 p,Quaternion r,float w){animator.SetIKPositionWeight(goal,w);animator.SetIKRotationWeight(goal,w);animator.SetIKPosition(goal,p);animator.SetIKRotation(goal,r);}
}
